// keccak_single: Keccak engine, 32 slices per clock. Generated by gen.py (M=16). Flip-flops only, no memories.
// dual=0: ONE core, Keccak-p[1600], lane i = {B_i, A_i}; job control = core 0.
// dual=1: TWO job-independent cores, Keccak-p[800] each (core 0 = A halves, core 1 = B halves).
// Shared, free running: the slot counter. One slot = 1 rotate cycle + 2 pass cycles = 3 clocks.
//   rotate cycle : rho for every lane (fixed wiring) with the one-bit theta correction folded in
//   pass cycles  : pi, chi, iota of this round and theta of the next, 16 slices per half per clock
// A job = 1 opening slot (theta only) + one slot per round. Private per core: state, round counter, range, constant.
// A job starts on the next slot boundary. An idle core holds its lanes.
module keccak_single(input clk, input rst, input dual,
    input [1:0] wr, input wxor, input [4:0] widx, input [63:0] wdata,    // lane write (bit 0: A half, bit 1: B half)
    input [1:0] clr,                                                     // zero the A / B halves of every lane
    input [4:0] ridx, output reg [63:0] rdata,                           // lane read, one clock later
    input [1:0] start, input [4:0] first0, input [4:0] last0, input [4:0] first1, input [4:0] last1,
    output [1:0] busy, output [1:0] qfull, output reg [1:0] err);        // err: sticky, an illegal request was ignored
  // rules, enforced here: no start while qfull or with first > last or last > 23; no lane write or clear to a busy core;
  // dual is sampled only while both cores are idle.                              // qfull: a request is waiting, do not pulse start
  localparam IDLE = 2'd0, PRE = 2'd1, RUN = 2'd2;
  reg [31:0] A [0:24]; reg [31:0] B [0:24];
  reg [1:0] cnt; reg [4:0] cpA, cpB; reg [31:0] rcA, rcB;
  reg [1:0] st0, st1, pend; reg th0, th1; reg [1:0] n_st0, n_st1; reg n_th0, n_th1; reg [4:0] n_ri0, n_ri1; reg [1:0] take;
  reg preA, preB, thA, thB, rotA, rotB, pasA, pasB, fp;        // per-half control, registered one clock ahead
  reg [24:0] wsA, wsB; reg wx; reg [63:0] wd;                  // lane write, one pipeline stage
  reg [4:0] ri0, rl0, pf0, pl0, qf0, ql0, ri1, rl1, pf1, pl1, qf1, ql1;
  function [4:0] par(input [24:0] s); integer x; begin
    for (x = 0; x < 5; x = x + 1) par[x] = s[x] ^ s[x+5] ^ s[x+10] ^ s[x+15] ^ s[x+20]; end endfunction
  function [24:0] pc(input [24:0] a, input rcb, input pre); reg [24:0] b; integer x, y, i; begin
    for (x = 0; x < 5; x = x + 1) for (y = 0; y < 5; y = y + 1) b[y + 5*((2*x + 3*y) % 5)] = a[x + 5*y];
    for (i = 0; i < 25; i = i + 1) pc[i] = pre ? a[i] : (b[i] ^ (~b[(i%5+1)%5 + 5*(i/5)] & b[(i%5+2)%5 + 5*(i/5)]) ^ ((i == 0) & rcb)); end endfunction
  function [24:0] th(input [24:0] s, input [4:0] c, input [4:0] p, input en); integer i; begin
    for (i = 0; i < 25; i = i + 1) th[i] = s[i] ^ (en & (c[(i%5+4)%5] ^ p[(i%5+1)%5])); end endfunction
  function [63:0] rcf(input [4:0] r); case (r)
    5'd0: rcf = 64'h0000000000000001;
    5'd1: rcf = 64'h0000000000008082;
    5'd2: rcf = 64'h800000000000808a;
    5'd3: rcf = 64'h8000000080008000;
    5'd4: rcf = 64'h000000000000808b;
    5'd5: rcf = 64'h0000000080000001;
    5'd6: rcf = 64'h8000000080008081;
    5'd7: rcf = 64'h8000000000008009;
    5'd8: rcf = 64'h000000000000008a;
    5'd9: rcf = 64'h0000000000000088;
    5'd10: rcf = 64'h0000000080008009;
    5'd11: rcf = 64'h000000008000000a;
    5'd12: rcf = 64'h000000008000808b;
    5'd13: rcf = 64'h800000000000008b;
    5'd14: rcf = 64'h8000000000008089;
    5'd15: rcf = 64'h8000000000008003;
    5'd16: rcf = 64'h8000000000008002;
    5'd17: rcf = 64'h8000000000000080;
    5'd18: rcf = 64'h000000000000800a;
    5'd19: rcf = 64'h800000008000000a;
    5'd20: rcf = 64'h8000000080008081;
    5'd21: rcf = 64'h8000000000008080;
    5'd22: rcf = 64'h0000000080000001;
    5'd23: rcf = 64'h8000000080008008;
    default: rcf = 64'h0; endcase endfunction
  reg du_r; reg [1:0] cl;
  wire du = 1'b0;
  wire [1:0] bad = {(first1 > last1) | (last1 > 5'd23), (first0 > last0) | (last0 > 5'd23)};
  wire [1:0] acc = start & ~pend & ~bad & {du, 1'b1};                    // accepted start pulses
  wire [1:0] bz = {du ? busy[1] : busy[0], busy[0]};                     // the core that owns each half is busy
  assign qfull = pend;
  assign busy = {(st1 != IDLE) | pend[1], (st0 != IDLE) | pend[0]};
  wire rot = (cnt == 0), last = (cnt == 2);
  wire [1:0] n_cnt = last ? 2'd0 : cnt + 2'd1;
  always @* begin                                                        // slot boundary: private job control
    n_st0 = st0; n_th0 = th0; n_ri0 = ri0; n_st1 = st1; n_th1 = th1; n_ri1 = ri1; take = 2'b00;
    if (last) begin
      case (st0)
        PRE: begin n_st0 = RUN; n_ri0 = pf0; n_th0 = (pf0 != pl0); end
        RUN: if (ri0 != rl0) begin n_ri0 = ri0 + 5'd1; n_th0 = ((ri0 + 5'd1) != rl0); end
             else if (pend[0]) begin n_st0 = PRE; n_th0 = 1'b1; take[0] = 1'b1; end
             else begin n_st0 = IDLE; n_th0 = 1'b0; end
        IDLE: if (pend[0]) begin n_st0 = PRE; n_th0 = 1'b1; take[0] = 1'b1; end
        default: begin n_st0 = IDLE; n_th0 = 1'b0; end
      endcase
      case (st1)
        PRE: begin n_st1 = RUN; n_ri1 = pf1; n_th1 = (pf1 != pl1); end
        RUN: if (ri1 != rl1) begin n_ri1 = ri1 + 5'd1; n_th1 = ((ri1 + 5'd1) != rl1); end
             else if (pend[1]) begin n_st1 = PRE; n_th1 = 1'b1; take[1] = 1'b1; end
             else begin n_st1 = IDLE; n_th1 = 1'b0; end
        IDLE: if (pend[1]) begin n_st1 = PRE; n_th1 = 1'b1; take[1] = 1'b1; end
        default: begin n_st1 = IDLE; n_th1 = 1'b0; end
      endcase
    end
  end
  wire [1:0] nsA = n_st0, nsB = du ? n_st1 : n_st0;
  wire [4:0] fxA = du ? cpA : cpB, fxB = du ? cpB : cpA;                 // theta correction for slice 0 of each half
  wire [63:0] rc0 = rcf(ri0), rc1 = rcf(ri1);
  // slice units
  wire [24:0] sl_A [0:15]; wire [24:0] sl_B [0:15]; wire [24:0] s_A [0:15]; wire [24:0] s_B [0:15];
  wire [4:0] c_A [0:15]; wire [4:0] c_B [0:15]; wire [24:0] o_A [0:15]; wire [24:0] o_B [0:15];
  wire [4:0] ciA = fp ? 5'd0 : cpA, ciB = fp ? 5'd0 : cpB;
  genvar g, j;
  generate for (j = 0; j < 16; j = j + 1) begin : u
    for (g = 0; g < 25; g = g + 1) begin : t
      assign sl_A[j][g] = A[g][j]; assign sl_B[j][g] = B[g][j];
    end
    assign s_A[j] = pc(sl_A[j], rcA[j], preA); assign s_B[j] = pc(sl_B[j], rcB[j], preB);
    assign c_A[j] = par(s_A[j]);                    assign c_B[j] = par(s_B[j]);
    if (j == 0) begin : f
      assign o_A[j] = th(s_A[j], c_A[j], ciA, thA);        assign o_B[j] = th(s_B[j], c_B[j], ciB, thB);
    end else begin : n
      assign o_A[j] = th(s_A[j], c_A[j], c_A[j-1], thA);   assign o_B[j] = th(s_B[j], c_B[j], c_B[j-1], thB);
    end
  end endgenerate
  // lanes with the slice-0 correction applied, then rho as fixed wiring
  wire [31:0] fA [0:24]; wire [31:0] fB [0:24]; wire [31:0] rA [0:24]; wire [31:0] rB [0:24];
  wire [31:0] nA [0:24]; wire [31:0] nB [0:24];
  generate for (g = 0; g < 25; g = g + 1) begin : l
    assign fA[g] = {A[g][31:1], A[g][0] ^ fxA[(g%5+1)%5]};
    assign fB[g] = {B[g][31:1], B[g][0] ^ fxB[(g%5+1)%5]};
    for (j = 0; j < 16; j = j + 1) begin : w
      assign nA[g][16+j] = o_A[j][g]; assign nB[g][16+j] = o_B[j][g];
    end
    assign nA[g][15:0] = A[g][31:16]; assign nB[g][15:0] = B[g][31:16];
  end endgenerate
  wire [63:0] x0 = {fB[0], fA[0]}; wire [63:0] y0 = x0;
  assign rA[0] = du ? fA[0] : y0[31:0]; assign rB[0] = du ? fB[0] : y0[63:32];
  wire [63:0] x1 = {fB[1], fA[1]}; wire [63:0] y1 = {x1[62:0], x1[63:63]};
  assign rA[1] = du ? {fA[1][30:0], fA[1][31:31]} : y1[31:0]; assign rB[1] = du ? {fB[1][30:0], fB[1][31:31]} : y1[63:32];
  wire [63:0] x2 = {fB[2], fA[2]}; wire [63:0] y2 = {x2[1:0], x2[63:2]};
  assign rA[2] = du ? {fA[2][1:0], fA[2][31:2]} : y2[31:0]; assign rB[2] = du ? {fB[2][1:0], fB[2][31:2]} : y2[63:32];
  wire [63:0] x3 = {fB[3], fA[3]}; wire [63:0] y3 = {x3[35:0], x3[63:36]};
  assign rA[3] = du ? {fA[3][3:0], fA[3][31:4]} : y3[31:0]; assign rB[3] = du ? {fB[3][3:0], fB[3][31:4]} : y3[63:32];
  wire [63:0] x4 = {fB[4], fA[4]}; wire [63:0] y4 = {x4[36:0], x4[63:37]};
  assign rA[4] = du ? {fA[4][4:0], fA[4][31:5]} : y4[31:0]; assign rB[4] = du ? {fB[4][4:0], fB[4][31:5]} : y4[63:32];
  wire [63:0] x5 = {fB[5], fA[5]}; wire [63:0] y5 = {x5[27:0], x5[63:28]};
  assign rA[5] = du ? {fA[5][27:0], fA[5][31:28]} : y5[31:0]; assign rB[5] = du ? {fB[5][27:0], fB[5][31:28]} : y5[63:32];
  wire [63:0] x6 = {fB[6], fA[6]}; wire [63:0] y6 = {x6[19:0], x6[63:20]};
  assign rA[6] = du ? {fA[6][19:0], fA[6][31:20]} : y6[31:0]; assign rB[6] = du ? {fB[6][19:0], fB[6][31:20]} : y6[63:32];
  wire [63:0] x7 = {fB[7], fA[7]}; wire [63:0] y7 = {x7[57:0], x7[63:58]};
  assign rA[7] = du ? {fA[7][25:0], fA[7][31:26]} : y7[31:0]; assign rB[7] = du ? {fB[7][25:0], fB[7][31:26]} : y7[63:32];
  wire [63:0] x8 = {fB[8], fA[8]}; wire [63:0] y8 = {x8[8:0], x8[63:9]};
  assign rA[8] = du ? {fA[8][8:0], fA[8][31:9]} : y8[31:0]; assign rB[8] = du ? {fB[8][8:0], fB[8][31:9]} : y8[63:32];
  wire [63:0] x9 = {fB[9], fA[9]}; wire [63:0] y9 = {x9[43:0], x9[63:44]};
  assign rA[9] = du ? {fA[9][11:0], fA[9][31:12]} : y9[31:0]; assign rB[9] = du ? {fB[9][11:0], fB[9][31:12]} : y9[63:32];
  wire [63:0] x10 = {fB[10], fA[10]}; wire [63:0] y10 = {x10[60:0], x10[63:61]};
  assign rA[10] = du ? {fA[10][28:0], fA[10][31:29]} : y10[31:0]; assign rB[10] = du ? {fB[10][28:0], fB[10][31:29]} : y10[63:32];
  wire [63:0] x11 = {fB[11], fA[11]}; wire [63:0] y11 = {x11[53:0], x11[63:54]};
  assign rA[11] = du ? {fA[11][21:0], fA[11][31:22]} : y11[31:0]; assign rB[11] = du ? {fB[11][21:0], fB[11][31:22]} : y11[63:32];
  wire [63:0] x12 = {fB[12], fA[12]}; wire [63:0] y12 = {x12[20:0], x12[63:21]};
  assign rA[12] = du ? {fA[12][20:0], fA[12][31:21]} : y12[31:0]; assign rB[12] = du ? {fB[12][20:0], fB[12][31:21]} : y12[63:32];
  wire [63:0] x13 = {fB[13], fA[13]}; wire [63:0] y13 = {x13[38:0], x13[63:39]};
  assign rA[13] = du ? {fA[13][6:0], fA[13][31:7]} : y13[31:0]; assign rB[13] = du ? {fB[13][6:0], fB[13][31:7]} : y13[63:32];
  wire [63:0] x14 = {fB[14], fA[14]}; wire [63:0] y14 = {x14[24:0], x14[63:25]};
  assign rA[14] = du ? {fA[14][24:0], fA[14][31:25]} : y14[31:0]; assign rB[14] = du ? {fB[14][24:0], fB[14][31:25]} : y14[63:32];
  wire [63:0] x15 = {fB[15], fA[15]}; wire [63:0] y15 = {x15[22:0], x15[63:23]};
  assign rA[15] = du ? {fA[15][22:0], fA[15][31:23]} : y15[31:0]; assign rB[15] = du ? {fB[15][22:0], fB[15][31:23]} : y15[63:32];
  wire [63:0] x16 = {fB[16], fA[16]}; wire [63:0] y16 = {x16[18:0], x16[63:19]};
  assign rA[16] = du ? {fA[16][18:0], fA[16][31:19]} : y16[31:0]; assign rB[16] = du ? {fB[16][18:0], fB[16][31:19]} : y16[63:32];
  wire [63:0] x17 = {fB[17], fA[17]}; wire [63:0] y17 = {x17[48:0], x17[63:49]};
  assign rA[17] = du ? {fA[17][16:0], fA[17][31:17]} : y17[31:0]; assign rB[17] = du ? {fB[17][16:0], fB[17][31:17]} : y17[63:32];
  wire [63:0] x18 = {fB[18], fA[18]}; wire [63:0] y18 = {x18[42:0], x18[63:43]};
  assign rA[18] = du ? {fA[18][10:0], fA[18][31:11]} : y18[31:0]; assign rB[18] = du ? {fB[18][10:0], fB[18][31:11]} : y18[63:32];
  wire [63:0] x19 = {fB[19], fA[19]}; wire [63:0] y19 = {x19[55:0], x19[63:56]};
  assign rA[19] = du ? {fA[19][23:0], fA[19][31:24]} : y19[31:0]; assign rB[19] = du ? {fB[19][23:0], fB[19][31:24]} : y19[63:32];
  wire [63:0] x20 = {fB[20], fA[20]}; wire [63:0] y20 = {x20[45:0], x20[63:46]};
  assign rA[20] = du ? {fA[20][13:0], fA[20][31:14]} : y20[31:0]; assign rB[20] = du ? {fB[20][13:0], fB[20][31:14]} : y20[63:32];
  wire [63:0] x21 = {fB[21], fA[21]}; wire [63:0] y21 = {x21[61:0], x21[63:62]};
  assign rA[21] = du ? {fA[21][29:0], fA[21][31:30]} : y21[31:0]; assign rB[21] = du ? {fB[21][29:0], fB[21][31:30]} : y21[63:32];
  wire [63:0] x22 = {fB[22], fA[22]}; wire [63:0] y22 = {x22[2:0], x22[63:3]};
  assign rA[22] = du ? {fA[22][2:0], fA[22][31:3]} : y22[31:0]; assign rB[22] = du ? {fB[22][2:0], fB[22][31:3]} : y22[63:32];
  wire [63:0] x23 = {fB[23], fA[23]}; wire [63:0] y23 = {x23[7:0], x23[63:8]};
  assign rA[23] = du ? {fA[23][7:0], fA[23][31:8]} : y23[31:0]; assign rB[23] = du ? {fB[23][7:0], fB[23][31:8]} : y23[63:32];
  wire [63:0] x24 = {fB[24], fA[24]}; wire [63:0] y24 = {x24[49:0], x24[63:50]};
  assign rA[24] = du ? {fA[24][17:0], fA[24][31:18]} : y24[31:0]; assign rB[24] = du ? {fB[24][17:0], fB[24][31:18]} : y24[63:32];
  integer k;
  always @(posedge clk) begin
    rdata <= {B[ridx], A[ridx]};
    wx <= wxor; wd <= wdata;
    if (rst) begin wsA <= 25'd0; wsB <= 25'd0; cl <= 2'b00; err <= 2'b00; du_r <= dual; st0 <= IDLE; st1 <= IDLE; pend <= 2'b00; cnt <= 0; th0 <= 1'b0; th1 <= 1'b0;
      preA <= 1'b0; preB <= 1'b0; thA <= 1'b0; thB <= 1'b0; rotA <= 1'b0; rotB <= 1'b0; pasA <= 1'b0; pasB <= 1'b0; fp <= 1'b0; end
    else begin
      wsA <= (wr[0] & ~bz[0]) ? (25'd1 << widx) : 25'd0; wsB <= (wr[1] & ~bz[1]) ? (25'd1 << widx) : 25'd0; cl <= clr & ~bz;
      err <= err | (start & {du, 1'b1} & ~acc) | ((wr | clr) & bz);
      if (busy == 2'b00 && start == 2'b00) du_r <= dual;
      cnt <= n_cnt;                                                      // shared slot counter, free running
      st0 <= n_st0; th0 <= n_th0; ri0 <= n_ri0; st1 <= n_st1; th1 <= n_th1; ri1 <= n_ri1;
      // a start pulse is latched; the latched request is taken at a slot boundary when the core is free.
      // The round range is copied at the take, so a queued job may carry a different range.
      if (take[0]) begin pend[0] <= 1'b0; pf0 <= qf0; pl0 <= ql0; end
      else if (acc[0]) begin pend[0] <= 1'b1; qf0 <= first0; ql0 <= last0; end
      if (take[1]) begin pend[1] <= 1'b0; pf1 <= qf1; pl1 <= ql1; end
      else if (acc[1]) begin pend[1] <= 1'b1; qf1 <= first1; ql1 <= last1; end
      if (last && st0 == PRE) rl0 <= pl0;
      if (last && st1 == PRE) rl1 <= pl1;
      preA <= (nsA == PRE); preB <= (nsB == PRE); thA <= n_th0; thB <= du ? n_th1 : n_th0; fp <= (n_cnt == 1);
      rotA <= (n_cnt == 0) & (nsA == RUN); rotB <= (n_cnt == 0) & (nsB == RUN);
      pasA <= (n_cnt != 0) & ((nsA == PRE) | (nsA == RUN)); pasB <= (n_cnt != 0) & ((nsB == PRE) | (nsB == RUN));
      if (rot) begin rcA <= rc0[31:0]; rcB <= du ? rc1[31:0] : rc0[63:32]; end
      else begin rcA <= rcA >> 16; rcB <= rcB >> 16; cpA <= c_A[15]; cpB <= c_B[15]; end
      for (k = 0; k < 25; k = k + 1) begin
        if (cl[0]) A[k] <= 32'd0;
        else if (wsA[k]) A[k] <= wx ? (A[k] ^ wd[31:0]) : wd[31:0];
        else if (rotA) A[k] <= rA[k];
        else if (pasA) A[k] <= nA[k];
        if (cl[1]) B[k] <= 32'd0;
        else if (wsB[k]) B[k] <= wx ? (B[k] ^ wd[63:32]) : wd[63:32];
        else if (rotB) B[k] <= rB[k];
        else if (pasB) B[k] <= nB[k];
      end
    end
  end
endmodule
